WITH exploded AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) x AS tier_value), scored AS (SELECT id, effective_from, RANK() OVER (ORDER BY tier_value DESC) AS tier_value_rank FROM exploded), with_windows AS (SELECT effective_from, tier_value_rank, PERCENT_RANK() OVER (ORDER BY tier_value_rank NULLS FIRST) AS tier_value_rank_percent_rank, CUME_DIST() OVER (ORDER BY tier_value_rank) AS tier_value_rank_cume_dist, RANK() OVER (ORDER BY tier_value_rank DESC) AS tier_value_rank_rank, PERCENT_RANK() OVER w_recent AS tier_value_rank_percent_rank_2, CUME_DIST() OVER (ORDER BY tier_value_rank NULLS LAST) AS tier_value_rank_cume_dist_2 FROM scored WHERE MONTH(effective_from) IN (2, 4, 11) WINDOW w_recent AS (ORDER BY tier_value_rank DESC NULLS FIRST)), valid AS (SELECT *, COALESCE(tier_value_rank_cume_dist, 0) AS tier_value_rank_cume_dist_filled FROM with_windows WHERE effective_from > DATE '2024-02-08'), base AS (SELECT tier_value_rank_percent_rank, tier_value_rank_cume_dist, tier_value_rank_rank, tier_value_rank_percent_rank_2, tier_value_rank_cume_dist_2, DAY(effective_from) AS effective_from_day, LAST_DAY(effective_from) AS effective_from_month_end FROM valid WHERE effective_from >= DATE '2024-03-22' AND tier_value_rank_percent_rank_2 >= 0.4) SELECT tier_value_rank_percent_rank, tier_value_rank_rank, tier_value_rank_percent_rank_2, tier_value_rank_cume_dist_2, effective_from_day FROM base;
